import{_ as t}from"./chunks/dtc-editor.DKK7pOGa.js";import{_ as n,o as r,c as i,a3 as a}from"./chunks/framework.B9qR_F1m.js";const b=JSON.parse('{"title":"DTC – Cartridges","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/dtc.md","filePath":"bereiche/dtc.md"}'),d={name:"bereiche/dtc.md"};function s(o,e,l,g,h,u){return r(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="dtc-–-cartridges" tabindex="-1">DTC – Cartridges <a class="header-anchor" href="#dtc-–-cartridges" aria-label="Permalink to &quot;DTC – Cartridges&quot;">​</a></h1><p>Seit DCS die <strong>Data Transfer Cartridge</strong> kennt, lädt der Jet Steerpoints, Funk und Gegenmaßnahmen aus einer Datei. Shardwing baut diese Cartridges für <strong>F-16C</strong> und <strong>F/A-18C</strong> – im nativen DCS-Format, als läge sie im DTC-Manager des Mission Editors.</p><p><img src="'+t+'" alt="DTC-Editor einer F-16C mit Steerpoints, Zielen und Bedrohungsringen auf der Karte" loading="lazy"></p><h2 id="eine-cartridge-anlegen" tabindex="-1">Eine Cartridge anlegen <a class="header-anchor" href="#eine-cartridge-anlegen" aria-label="Permalink to &quot;Eine Cartridge anlegen&quot;">​</a></h2><p>Reiter <strong>DTC</strong> eines Flights:</p><table tabindex="0"><thead><tr><th>Knopf</th><th>Was passiert</th></tr></thead><tbody><tr><td><strong>Neu aus Route</strong></td><td>Übernimmt die Wegpunkte als Steerpoints, die Funk-Presets und <strong>nur die Bedrohungen, die für diesen Flight freigegeben sind</strong>. CMDS bleibt standardmäßig beim Piloten. Die übliche Wahl.</td></tr><tr><td><strong>Neu leer</strong></td><td>Leere Cartridge – mit Funk, CMDS und Schaltern aus deiner Standard-Cartridge, falls du eine festgelegt hast.</td></tr><tr><td><strong>Aus Datei …</strong></td><td>Eine vorhandene <code>.dtc</code> laden, z. B. die eigene aus <code>Saved Games\\DCS\\DTC</code>. Hat die Datei CMDS-Programme, bleiben sie drin (der Schalter <strong>überschreiben</strong> steht dann an).</td></tr></tbody></table><p>Eine Cartridge in der Mission ist eine <strong>Datei in der .miz</strong>. Sie hängt an einem oder mehreren Flugzeugen; im Kopf des Editors siehst du, an welchen (<em>an Aerial-1</em>). Mehrere Flights können sich eine Cartridge teilen.</p><h2 id="der-kopf-des-editors" tabindex="-1">Der Kopf des Editors <a class="header-anchor" href="#der-kopf-des-editors" aria-label="Permalink to &quot;Der Kopf des Editors&quot;">​</a></h2><ul><li><strong>Name</strong> – wird der Dateiname in der .miz.</li><li><strong>an …</strong> – welche Units des Flights die Cartridge laden.</li><li><strong>AutoLoad</strong> – lädt beim Spawn automatisch. Ohne AutoLoad lädt der Pilot sie selbst auf der DTE-Seite (F-16) bzw. MUMI-Seite (F/A-18).</li><li><strong>Als meine Standard-Cartridge</strong> – Funk, CMDS und Schalter dieser Cartridge werden die Vorlage für <em>Neu leer</em> (ohne Wegpunkte, Linien, Threats).</li><li><strong>.dtc exportieren</strong> – als einzelne Datei speichern, z. B. für <code>Saved Games\\DCS\\DTC</code>.</li><li><strong>Entfernen</strong> – Cartridge aus der Mission nehmen.</li></ul><h2 id="bereiche-und-„uberschreiben" tabindex="-1">Bereiche und „überschreiben“ <a class="header-anchor" href="#bereiche-und-„uberschreiben" aria-label="Permalink to &quot;Bereiche und „überschreiben“&quot;">​</a></h2><p>Eine Cartridge besteht aus Bereichen (NAV, COMM, CMDS …). Jeder Bereich hat den Schalter <strong>überschreiben</strong>:</p><ul><li><strong>an</strong> – wird beim Laden in den Jet geschrieben.</li><li><strong>aus</strong> – fehlt in der .dtc; der Jet behält, was er hat.</li></ul><p>So kannst du z. B. Steerpoints und Funk vorgeben, aber die <strong>CMDS-Programme des Piloten unangetastet</strong> lassen.</p><p><strong>Übernehmen aus …</strong> holt einen Bereich aus einer anderen Cartridge – etwa die eigenen CMDS-Programme.</p><h2 id="f-16c" tabindex="-1">F-16C <a class="header-anchor" href="#f-16c" aria-label="Permalink to &quot;F-16C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Steerpoints</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>NAV</strong></td><td>1–24</td><td>Steerpoints mit Koordinate, Elevation, TOS, Offset Aimpoints (OA1/OA2), Zuordnung zu Route 1–3. Steerpoint 25 ist der Bullseye.</td></tr><tr><td><strong>Geo Lines</strong></td><td>31–55</td><td>Linien auf dem HSD – aus Zeichnungen (FLOT, Kill Box, CAP …) übernommen oder von Hand gesetzt, bis zu vier Linien.</td></tr><tr><td><strong>Threats</strong></td><td>56–70</td><td>Threat-Ringe mit DCS-Typ und Reichweite – nur freigegebene. <strong>Von Intel übernehmen</strong> hängt die freigegebenen Threats nahe der Route an, die noch fehlen. Den <strong>Typ</strong> wählst du aus SA-2, SA-3, SA-5, SA-6, SA-11 oder <em>Custom</em>; ein Typ bringt Ring und HSD-Text des Mission Editors mit.</td></tr><tr><td><strong>DEST</strong></td><td>81–99</td><td>Zielpunkte, z. B. Flugplätze.</td></tr><tr><td><strong>VIP/VRP</strong></td><td>je 1</td><td>Visual Initial Point bzw. Visual Reference Point mit Peilung/Distanz/Elevation zu Ziel und PUP.</td></tr><tr><td><strong>COMM</strong></td><td>–</td><td>COMM1 (UHF) und COMM2 (VHF/FM), 20 Presets je Radio.</td></tr><tr><td><strong>CMDS</strong></td><td>–</td><td>Chaff/Flare-Programme. Standard: <em>nicht überschreiben</em>.</td></tr></tbody></table><h3 id="steerpoints-bearbeiten" tabindex="-1">Steerpoints bearbeiten <a class="header-anchor" href="#steerpoints-bearbeiten" aria-label="Permalink to &quot;Steerpoints bearbeiten&quot;">​</a></h3><ul><li><strong>Klick auf die Karte</strong> setzt einen neuen Steerpoint, ziehen verschiebt ihn. Ist die Liste voll (z. B. 24 NAV-Punkte), endet das Setzen auf der Karte von selbst.</li><li>In der Tabelle: Typ, Notiz, Koordinate, <strong>Elev ft</strong>, <strong>TOS</strong>, OA1/OA2 und die Routen (1, 2, 3 – wie im DTC-Manager).</li><li><strong>Elev = Boden (alle)</strong> setzt die Elevation aller Punkte aus Geländedaten (SRTM, kann von DCS um ein paar Meter abweichen).</li><li>Nur bei getrennt geplanten Zeiten: <strong>TOS verschieben</strong> um ±1 oder ±5 Minuten, <strong>TOS aus Route</strong> übernimmt die ETAs der Missionsroute. TOS wird in Zulu gespeichert; <kbd>↑</kbd>/<kbd>↓</kbd> im Zeitfeld verstellt die Stelle unter dem Cursor, mit <kbd>Shift</kbd> in Zehnerschritten.</li><li><strong>⌖ auf …</strong> unter der Koordinate setzt den Steerpoint auf einen Ort des Designers: eure Sollzeiten mit Ort, den Tanker-Track und unter <em>Weitere Planungspunkte</em> jeden Planungspunkt eurer Seite (Fix, RV, CP …), auch ohne Zeit für euren Flight. So legt ihr allgemeine Wegpunkte, ohne Koordinaten abzutippen.</li><li>Pfeile ↑ ↓ ändern die Reihenfolge, × löscht.</li></ul><h3 id="zeiten-flugplan-oder-getrennt" tabindex="-1">Zeiten: Flugplan oder getrennt <a class="header-anchor" href="#zeiten-flugplan-oder-getrennt" aria-label="Permalink to &quot;Zeiten: Flugplan oder getrennt&quot;">​</a></h3><p>Die Zeiten der Steerpoints (TOS, bei der F/A-18C ETA) rechnet der Flugplan im Reiter <a href="./flights#route">Route</a>. Eine neue Cartridge ist daran <strong>gekoppelt</strong>: Die Zeitspalte hier zeigt nur an, und beim Speichern oder beim Export als .dtc stehen die Zeiten des Flugplans in der Cartridge.</p><p>Der Schalter <strong>Zeiten getrennt planen</strong> löst die Kopplung. Dann tippst du die Zeiten hier selbst, und der Flugplan ändert sie nicht mehr. Cartridges aus einer Datei und solche aus der Mission sind zunächst getrennt geplant; im Reiter Route koppelt sie <strong>An den Flugplan koppeln</strong>.</p><h3 id="geo-lines-aus-zeichnungen" tabindex="-1">Geo Lines aus Zeichnungen <a class="header-anchor" href="#geo-lines-aus-zeichnungen" aria-label="Permalink to &quot;Geo Lines aus Zeichnungen&quot;">​</a></h3><p><strong>Aus Grafik übernehmen …</strong> bzw. <strong>Aus Zeichnung übernehmen</strong> macht aus einer FLOT, Kill Box oder CAP-Station eine Geo Line – in die nächste freie Linie oder an eine bestimmte angehängt. Flächen werden geschlossen, Racetracks gestuft.</p><h2 id="f-a-18c" tabindex="-1">F/A-18C <a class="header-anchor" href="#f-a-18c" aria-label="Permalink to &quot;F/A-18C&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bereich</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>Waypoints</strong></td><td>1–59. Jeder Punkt liegt auf einer Route (<strong>1</strong>, <strong>2</strong> oder <strong>3</strong>, in den Farben der Karte) oder auf keiner; die Reihenfolge einer Route ist die der Tabelle, höchstens 15 Punkte je Route. Höhe, Geschwindigkeit und TGT gehören zum Leg auf dieser Route. Dieselbe Auswahl steht im Reiter <a href="./flights#der-flugplan">Route</a>.</td></tr><tr><td><strong>SA-Seite</strong></td><td>CAP-Punkte (Racetrack mit Anker, Kurs, Leg, Kurve links/rechts), FLOT, FAOR und Korridor, MEZ-Ringe (Threats; der <strong>Typ</strong> wie im Mission Editor setzt Text und Radius; <strong>Von Intel übernehmen</strong> hängt die für den Flight freigegebenen Bedrohungen nahe der Route an, die noch fehlen). Alle Punkte lassen sich auf der Karte ziehen.</td></tr><tr><td><strong>COMM</strong></td><td>Presets mit Kanalnamen, die auf dem UFC erscheinen. Die Hornet nimmt UHF und VHF auf beiden Radios.</td></tr><tr><td><strong>TACAN</strong></td><td>Liste der Stationen im Jet: Kennung, Kanal (Band X), Name, Elevation, Koordinate. <strong>Station der Karte anhängen</strong> übernimmt eine Bodenstation der DCS-Karte. Ohne „überschreiben“ behält der Jet seine eigene Liste.</td></tr><tr><td><strong>CMDS</strong></td><td>ALR-67-Programme</td></tr></tbody></table><h2 id="comm" tabindex="-1">COMM <a class="header-anchor" href="#comm" aria-label="Permalink to &quot;COMM&quot;">​</a></h2><p>Jede Station auf jedem Kanal, im Band nach Wahl. Die F-16 nimmt auf COMM1 nur UHF, auf COMM2 VHF/FM; die Hornet beides. Einfacher als Kanal für Kanal: den paketweiten <a href="./kneeboards#comm-plan">Comm Plan</a> anlegen und mit einem Knopf in alle Cartridges übernehmen.</p><h2 id="personliche-cartridges" tabindex="-1">Persönliche Cartridges <a class="header-anchor" href="#personliche-cartridges" aria-label="Permalink to &quot;Persönliche Cartridges&quot;">​</a></h2><p>Beim gemeinsamen Planen teilen sich oft mehrere Flugzeuge eine Cartridge. Ändert ein Pilot <strong>seine CMDS oder Farben</strong>, legt Shardwing eine persönliche Kopie an (<code>&lt;Cartridge&gt; - &lt;Callsign&gt;</code>). Sein Jet lädt die Kopie, alle anderen behalten die gemeinsame. Eine Cartridge, die mehrere Flights laden, ändert nur der Designer – der Flight kann sich eine eigene Kopie anlegen.</p><h2 id="einzelne-cartridges" tabindex="-1">Einzelne Cartridges <a class="header-anchor" href="#einzelne-cartridges" aria-label="Permalink to &quot;Einzelne Cartridges&quot;">​</a></h2><p>Öffnest du eine <code>.dtc</code>-Datei ohne Mission, steht sie links unter <strong>Einzelne Cartridges</strong>. Du kannst sie bearbeiten und wieder als <code>.dtc</code> speichern – etwa deine persönliche Standard-Cartridge.</p>',31)])])}const p=n(d,[["render",s]]);export{b as __pageData,p as default};
